mapper.select:

SELECT /* getUserMenuDtl */

  FROM TM_URMENU
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}



  SELECT /* getUserSubMenuList */

    FROM TM_URMENU
   WHERE MENU_NUMB = #{menuNumb}
     AND SUBX_NUMB != #{topMenuSubxNumb}
ORDER BY NVL(SORT_ORDR, 9999)
       , TO_NUMBER(SUBX_NUMB)

mapper.insert:
/* setUserMenu */
INSERT INTO TM_URMENU (
            MENU_NUMB
          , SUBX_NUMB
          , MENU_NAME
          , MENU_URLX
          , SORT_ORDR
          , SHOW_YSNO
          , USEE_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{menuNumb}
          , #{subxNumb}
          , #{menuName}
          , #{menuUrlx}
          , #{sortOrdr,jdbcType=NUMERIC}
          , #{showYsno}
          , #{useeYsno}
          , #{regiAdmn}
          , SYSTIMESTAMP
          , #{updtAdmn}
          , SYSTIMESTAMP
)

mapper.update:
UPDATE /* uptUserMenu */
       TM_URMENU
   SET MENU_NAME = #{menuName}
     , MENU_URLX = #{menuUrlx}
     , SORT_ORDR = #{sortOrdr,jdbcType=NUMERIC}
     , SHOW_YSNO = #{showYsno}
     , USEE_YSNO = #{useeYsno}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = SYSTIMESTAMP
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}

mapper.delete:
DELETE /* delUserMenu */
  FROM TM_URMENU
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}
